import sys
from collections import defaultdict, deque

input = sys.stdin.read().split()
n = int(input[0])
p = [0] * n
c = [0] * n
for i in range(n):
    p[i] = int(input[2 * i + 1])
    c[i] = int(input[2 * i + 2])

adj = defaultdict(list)
root = -1
for i in range(n):
    if p[i] == 0:
        root = i
    else:
        adj[p[i] - 1].append(i)

def dfs(node, available):
    if node == -1:
        return True
    if available < c[node]:
        return False
    children = sorted([(c[child], child) for child in adj[node]], reverse=True)
    used = 0
    for cc, child in children:
        if not dfs(child, available - used - 1):
            return False
        used += cc + 1
    a[node] = available - used
    return True

a = [-1] * n
if dfs(root, n):
